require_once __DIR__.'/core/bootstrap.php';$admin=require_admin($pdo);$id=trim((string)($_GET['id']??''));$stmt=$pdo->prepare('SELECT * FROM users WHERE id=:id');$stmt->execute(['id'=>$id]);$target=$stmt->fetch();if(!$target){http_response_code(404);exit('User not found.');}$error=null;
if(request_method('POST')){verify_csrf();$username=trim((string)($_POST['username']??''));$university=(string)($_POST['university']??'');$rating=int_between($_POST['rating']??1200,0,5000,1200);$rank=trim((string)($_POST['rank']??'Newbie'));$role=in_array($_POST['role']??'user',['user','admin'],true)?(string)$_POST['role']:'user';$password=(string)($_POST['password']??'');if(!preg_match('/^[A-Za-z0-9_]{3,32}$/',$username)){$error='Username must be 3–32 characters using letters, numbers or underscore.';}elseif($password!==''&&strlen($password)<8){$error='New password must be at least 8 characters.';}elseif($id===$admin['id']&&$role!=='admin'){$error='You cannot remove your own administrator role while signed in.';}else{try{if($password!==''){$sql='UPDATE users SET username=:username,university=:university,rating=:rating,`rank`=:rank,role=:role,password=:password WHERE id=:id';$params=['username'=>$username,'university'=>$university?:null,'rating'=>$rating,'rank'=>$rank,'role'=>$role,'password'=>password_hash($password,PASSWORD_DEFAULT),'id'=>$id];}else{$sql='UPDATE users SET username=:username,university=:university,rating=:rating,`rank`=:rank,role=:role WHERE id=:id';$params=['username'=>$username,'university'=>$university?:null,'rating'=>$rating,'rank'=>$rank,'role'=>$role,'id'=>$id];}$pdo->prepare($sql)->execute($params);flash('success','User updated.');redirect('database.php');}catch(PDOException){$error='Update failed. The username may already be in use.';}}}
$universities=$pdo->query('SELECT name FROM universities ORDER BY name')->fetchAll(PDO::FETCH_COLUMN);$pageTitle='Edit User';include __DIR__.'/includes/header.php';
?>
<div class="page-head"><div><div class="eyebrow">Administrator</div><h1>Edit <?=e($target['username'])?></h1><p>Update account metadata, role, rating, or securely replace the password.</p></div><a class="btn btn-secondary" href="database.php"><i class="bi bi-arrow-left"></i>Back</a></div><?php if($error):?><div class="toast-banner danger"><?=e($error)?></div><?php endif;?>
<div class="card card-pad"><form method="post"><?=csrf_field()?><div class="form-grid"><div><label class="form-label">User ID</label><input class="form-control" value="<?=e($target['id'])?>" readonly></div><div><label class="form-label">Username</label><input class="form-control" name="username" value="<?=e($target['username'])?>" required></div><div><label class="form-label">University</label><select class="form-select" name="university"><option value="">No university</option><?php foreach($universities as $u):?><option <?=$target['university']===$u?'selected':''?>><?=e($u)?></option><?php endforeach;?></select></div><div><label class="form-label">Role</label><select class="form-select" name="role"><option value="user" <?=$target['role']==='user'?'selected':''?>>User</option><option value="admin" <?=$target['role']==='admin'?'selected':''?>>Admin</option></select></div><div><label class="form-label">Rating</label><input class="form-control" type="number" min="0" max="5000" name="rating" value="<?=(int)$target['rating']?>"></div><div><label class="form-label">Rank</label><input class="form-control" name="rank" value="<?=e($target['rank'])?>"></div><div style="grid-column:1/-1"><label class="form-label">New password (optional)</label><input class="form-control" type="password" name="password" minlength="8"></div></div><button class="btn btn-primary" style="margin-top:14px">Save changes</button></form></div>
